#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int knapsack(vector<int>& weight, vector<int>& value, int W) {
    int n = weight.size();
    vector<vector<int>> dp(n + 1, vector<int>(W + 1, 0));

    for (int i = 1; i <= n; i++) {
        for (int w = 0; w <= W; w++) {
            dp[i][w] = dp[i - 1][w]; // 담지 않는 경우
            if (w >= weight[i - 1]) {
                dp[i][w] = max(dp[i][w],
                    dp[i - 1][w - weight[i - 1]] + value[i - 1]); // 담는 경우
            }
        }
    }

    return dp[n][W];
}

int main() {
    vector<int> weight = {2, 3, 4, 5};
    vector<int> value  = {3, 4, 5, 6};
    int W = 8;
    cout << knapsack(weight, value, W) << "\n"; // 10
    return 0;
}
